-- TASK-029 MariaDB baseline, matches docs/DATABASE-SCHEMA.md (simplified)
CREATE DATABASE IF NOT EXISTS faizen CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE faizen;
CREATE TABLE IF NOT EXISTS builds (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, status ENUM('DRAFT','COMING_SOON','BETA','AVAILABLE','ARCHIVED') NOT NULL DEFAULT 'DRAFT', summary TEXT, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL);
CREATE TABLE IF NOT EXISTS solutions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, status ENUM('DRAFT','COMING_SOON','BETA','AVAILABLE','ARCHIVED') NOT NULL DEFAULT 'DRAFT', pricing VARCHAR(100), url VARCHAR(500));
CREATE TABLE IF NOT EXISTS services (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, status ENUM('ACTIVE','INACTIVE','ARCHIVED') NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS articles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, status ENUM('DRAFT','PUBLISHED','ARCHIVED') NOT NULL DEFAULT 'DRAFT', category VARCHAR(100), content MEDIUMTEXT);
CREATE TABLE IF NOT EXISTS hero_slides (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, type ENUM('BUILD','SOLUTION','CUSTOM') NOT NULL, reference_id BIGINT UNSIGNED NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, starts_at DATETIME NULL, ends_at DATETIME NULL);
CREATE TABLE IF NOT EXISTS media (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, filename VARCHAR(255) NOT NULL, path VARCHAR(500) NOT NULL, mime_type VARCHAR(100), size BIGINT UNSIGNED);
CREATE TABLE IF NOT EXISTS inquiries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, intent ENUM('existing','custom','partnership','other') NOT NULL, name VARCHAR(100) NOT NULL, contact_type ENUM('email','whatsapp') NOT NULL, contact_value VARCHAR(255) NOT NULL, brief_description TEXT NOT NULL, status VARCHAR(50) DEFAULT 'new', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS company_settings (id BIGINT UNSIGNED PRIMARY KEY DEFAULT 1, company_name VARCHAR(255), tagline VARCHAR(255), description TEXT, logo VARCHAR(500), favicon VARCHAR(500), email VARCHAR(255), phone VARCHAR(50), address TEXT, social_media JSON);
